/* 2026_11_20_000001_complete_packed_cabinets */
update `cabinets` set `status` = 'completed', `progress` = 100 where `deleted_at` is null and `status` not in ('completed', 'on_hold') and EXISTS (SELECT 1 FROM cabinet_checklists cc
            JOIN cabinet_subtasks cs ON cs.id = cc.cabinet_subtask_id AND cs.deleted_at IS NULL
            JOIN cabinet_tasks ct ON ct.id = cs.cabinet_task_id AND ct.deleted_at IS NULL
            WHERE ct.cabinet_id = cabinets.id AND cc.deleted_at IS NULL AND cc.is_completed = 1 AND REPLACE(cc.name, ' ', '') = 'ห่อตู้เสร็จสิ้น') and NOT EXISTS (SELECT 1 FROM cabinet_checklists cc
            JOIN cabinet_subtasks cs ON cs.id = cc.cabinet_subtask_id AND cs.deleted_at IS NULL
            JOIN cabinet_tasks ct ON ct.id = cs.cabinet_task_id AND ct.deleted_at IS NULL
            WHERE ct.cabinet_id = cabinets.id AND cc.deleted_at IS NULL AND cc.is_completed = 0 AND REPLACE(cc.name, ' ', '') NOT IN ('แจ้งเปิดบิล', 'ดำเนินการส่งมอบ', 'ส่งมอบเสร็จสิ้น'));
INSERT INTO `migrations` (`migration`, `batch`) SELECT '2026_11_20_000001_complete_packed_cabinets', COALESCE(MAX(`batch`), 0) + 1 FROM `migrations`;
